// Shared setup for the plan walkthrough specs (chat-plans, plan-validation):
// the canned deltas the server's stub OpenSpec CLI serves, and a git
// repository whose OpenSpec root registers the changes the walkthroughs'
// plans name — so a validation resolves them as registered and can reach a
// Ready report through the UI's own Validate button. The stub itself is
// generated by playwright.config.ts into the e2e stub-bin; nothing here
// spawns the real CLI from the test worker.
import { expect, type Locator } from '@playwright/test'
import { execFileSync } from 'node:child_process'
import { mkdirSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

/** One canned delta touch the stub serves for a change. */
export interface StubTouch {
  capability: string
  operation: string
  requirement: string
}

/**
 * The canned deltas the stub CLI serves, one file per change: the spec
 * rewrites them between steps (or sets them once up front).
 */
export function serveDeltas(deltas: Record<string, readonly StubTouch[]>): void {
  const dir = join(process.env.E2E_TMUX_TMPDIR!, 'openspec-deltas')
  mkdirSync(dir, { recursive: true })
  for (const [change, touches] of Object.entries(deltas)) {
    writeFileSync(
      join(dir, `${change}.json`),
      JSON.stringify(touches.map(touch => ({
        spec: touch.capability, operation: touch.operation,
        requirement: { name: touch.requirement }, description: `${change} ${touch.requirement}`,
      }))),
    )
  }
}

/**
 * A git repository whose OpenSpec root registers each named change (a
 * proposal and a chat spec file), plus the team's group files, so a plan
 * naming the changes validates as registered. Returns nothing; callers pass
 * the root as the chat's project path.
 */
export function initPlanRepository(root: string, changes: readonly string[], groups: Record<string, string>): void {
  execFileSync('git', ['init', '-q', root])
  for (const change of changes) {
    mkdirSync(join(root, 'openspec', 'changes', change, 'specs', 'chat'), { recursive: true })
    writeFileSync(join(root, 'openspec', 'changes', change, 'proposal.md'), `# ${change}\n`)
    writeFileSync(join(root, 'openspec', 'changes', change, 'specs', 'chat', 'spec.md'), '## ADDED Requirements\n### Requirement: Presence\n')
  }
  mkdirSync(join(root, '.kawai', 'groups'), { recursive: true })
  for (const [id, body] of Object.entries(groups)) {
    writeFileSync(join(root, '.kawai', 'groups', `${id}.md`), body)
  }
}

/** Validate one revision through the UI and wait for its standing to read Ready. */
export async function validateUntilReady(panel: { getByTestId: (id: string) => Locator }, revision: number): Promise<void> {
  await panel.getByTestId(`plan-validate-${revision}`).click()
  await expect(panel.getByTestId(`plan-validation-${revision}-standing`)).toContainText('Ready', { timeout: 20_000 })
}

